import{_ as d,o as e,c as s,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CROSSTABS.md","filePath":"manual-en/CROSSTABS.md","lastUpdated":1785684581000}'),o={name:"manual-en/CROSSTABS.md"};function n(r,t,i,c,p,l){return e(),s("div",null,[...t[0]||(t[0]=[a(`<h3 id="_15-6-crosstabs" tabindex="-1">15.6 CROSSTABS <a class="header-anchor" href="#_15-6-crosstabs" aria-label="Permalink to &quot;15.6 CROSSTABS&quot;">​</a></h3><pre><code>CROSSTABS
        /TABLES=var_list BY var_list [BY var_list]…
        /MISSING={TABLE,INCLUDE,REPORT}
        /FORMAT={TABLES,NOTABLES}
                {AVALUE,DVALUE}
        /CELLS={COUNT,ROW,COLUMN,TOTAL,EXPECTED,RESIDUAL,SRESIDUAL,
                ASRESIDUAL,ALL,NONE}
        /COUNT={ASIS,CASE,CELL}
               {ROUND,TRUNCATE}
        /STATISTICS={CHISQ,PHI,CC,LAMBDA,UC,BTAU,CTAU,RISK,GAMMA,D,
                     KAPPA,ETA,CORR,ALL,NONE}
        /BARCHART

(Integer mode.)
        /VARIABLES=var_list (low,high)…
</code></pre><p>The <code>CROSSTABS</code> procedure displays crosstabulation tables requested by the user. It can calculate several statistics for each cell in the crosstabulation tables. In addition, a number of statistics can be calculated for each table itself.</p><p>The <code>TABLES</code> subcommand is used to specify the tables to be reported. Any number of dimensions is permitted, and any number of variables per dimension is allowed. The <code>TABLES</code> subcommand may be repeated as many times as needed. This is the only required subcommand in <em>general mode</em>.</p><p>Occasionally, one may want to invoke a special mode called <em>integer mode</em>. Normally, in general mode, PSPP automatically determines what values occur in the data. In integer mode, the user specifies the range of values that the data assumes. To invoke this mode, specify the <code>VARIABLES</code> subcommand, giving a range of data values in parentheses for each variable to be used on the <code>TABLES</code> subcommand. Data values inside the range are truncated to the nearest integer, then assigned to that value. If values occur outside this range, they are discarded. When it is present, the <code>VARIABLES</code> subcommand must precede the <code>TABLES</code> subcommand.</p><p>In general mode, numeric and string variables may be specified on TABLES. In integer mode, only numeric variables are allowed.</p><p>The <code>MISSING</code> subcommand determines the handling of user-missing values. When set to <code>TABLE</code>, the default, missing values are dropped on a table by table basis. When set to <code>INCLUDE</code>, user-missing values are included in tables and statistics. When set to <code>REPORT</code>, which is allowed only in integer mode, user-missing values are included in tables but marked with a footnote and excluded from statistical calculations.</p><p>The <code>FORMAT</code> subcommand controls the characteristics of the crosstabulation tables to be displayed. It has a number of possible settings:</p><ul><li><code>TABLES</code>, the default, causes crosstabulation tables to be output. <code>NOTABLES</code>, which is equivalent to <code>CELLS=NONE</code>, suppresses them.</li><li><code>AVALUE</code>, the default, causes values to be sorted in ascending order. <code>DVALUE</code> asserts a descending sort order.</li></ul><p>The <code>CELLS</code> subcommand controls the contents of each cell in the displayed crosstabulation table. The possible settings are:</p><p>COUNT</p><p>Frequency count.</p><p>ROW</p><p>Row percent.</p><p>COLUMN</p><p>Column percent.</p><p>TOTAL</p><p>Table percent.</p><p>EXPECTED</p><p>Expected value.</p><p>RESIDUAL</p><p>Residual.</p><p>SRESIDUAL</p><p>Standardized residual.</p><p>ASRESIDUAL</p><p>Adjusted standardized residual.</p><p>ALL</p><p>All of the above.</p><p>NONE</p><p>Suppress cells entirely.</p><p>‘/CELLS’ without any settings specified requests <code>COUNT</code>, <code>ROW</code>, <code>COLUMN</code>, and <code>TOTAL</code>. If <code>CELLS</code> is not specified at all then only <code>COUNT</code> is selected.</p><p>By default, crosstabulation and statistics use raw case weights, without rounding. Use the <code>/COUNT</code> subcommand to perform rounding: CASE rounds the weights of individual weights as cases are read, CELL rounds the weights of cells within each crosstabulation table after it has been constructed, and ASIS explicitly specifies the default non-rounding behavior. When rounding is requested, ROUND, the default, rounds to the nearest integer and TRUNCATE rounds toward zero.</p><p>The <code>STATISTICS</code> subcommand selects statistics for computation:</p><p>CHISQ</p><p>Pearson chi-square, likelihood ratio, Fisher’s exact test, continuity correction, linear-by-linear association.</p><p>PHI</p><p>Phi.</p><p>CC</p><p>Contingency coefficient.</p><p>LAMBDA</p><p>Lambda.</p><p>UC</p><p>Uncertainty coefficient.</p><p>BTAU</p><p>Tau-b.</p><p>CTAU</p><p>Tau-c.</p><p>RISK</p><p>Risk estimate.</p><p>GAMMA</p><p>Gamma.</p><p>D</p><p>Somers’ D.</p><p>KAPPA</p><p>Cohen’s Kappa.</p><p>ETA</p><p>Eta.</p><p>CORR</p><p>Spearman correlation, Pearson’s r.</p><p>ALL</p><p>All of the above.</p><p>NONE</p><p>No statistics.</p><p>Selected statistics are only calculated when appropriate for the statistic. Certain statistics require tables of a particular size, and some statistics are calculated only in integer mode.</p><p>‘/STATISTICS’ without any settings selects CHISQ. If the <code>STATISTICS</code> subcommand is not given, no statistics are calculated.</p><p>The ‘/BARCHART’ subcommand produces a clustered bar chart for the first two variables on each table. If a table has more than two variables, the counts for the third and subsequent levels are aggregated and the chart is produced as if there were only two variables.</p><p><strong>Please note:</strong> Currently the implementation of <code>CROSSTABS</code> has the following limitations:</p><ul><li>Significance of some directional measures is not calculated.</li><li>Asymptotic standard error is not calculated for Goodman and Kruskal’s tau or symmetric Somers’ d.</li><li>Approximate T is not calculated for symmetric uncertainty coefficient.</li></ul><p>Fixes for any of these deficiencies would be welcomed.</p><h4 id="_15-6-1-crosstabs-example" tabindex="-1">15.6.1 Crosstabs Example <a class="header-anchor" href="#_15-6-1-crosstabs-example" aria-label="Permalink to &quot;15.6.1 Crosstabs Example&quot;">​</a></h4><p>A researcher wishes to know if, in an industry, a person’s sex is related to the person’s occupation. To investigate this, she has determined that the personnel.sav is a representative, randomly selected sample of persons. The researcher’s null hypothesis is that a person’s sex has no relation to a person’s occupation. She uses a chi-squared test of independence to investigate the hypothesis.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&quot;personnel.sav&quot;.  crosstabs 	/tables= occupation by sex 	/cells = count expected 	/statistics=chisq.</span></span></code></pre></div><p><strong>Example 15.3:</strong> Running crosstabs on the <strong>sex</strong> and <strong>occupation</strong> variables</p><p>The syntax in Example 15.3 conducts a chi-squared test of independence. The line <code>/tables = occupation by sex</code> indicates that <strong>occupation</strong> and <strong>sex</strong> are the variables to be tabulated. To do this using the graphic user interface you must place these variable names respectively in the ‘Row’ and ‘Column’ fields as shown in Screenshot 15.3.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.3:</strong> The Crosstabs dialog box with the <strong>sex</strong> and <strong>occupation</strong> variables selected</p><p>Similarly, the ‘Cells’ button shows a dialog box to select the <code>count</code> and <code>expected</code> options. All other cell options can be deselected for this test.</p><p>You would use the ‘Format’ and ‘Statistics’ buttons to select options for the <code>FORMAT</code> and <code>STATISTICS</code> subcommands. In this example, the ‘Statistics’ requires only the ‘Chisq’ option to be checked. All other options should be unchecked. No special settings are required from the ‘Format’ dialog.</p><p>As shown in Results 15.1 <code>CROSSTABS</code> generates a contingency table containing the observed count and the expected count of each sex and each occupation. The expected count is the count which would be observed if the null hypothesis were true.</p><p>The significance of the Pearson Chi-Square value is very much larger than the normally accepted value of 0.05 and so one cannot reject the null hypothesis. Thus the researcher must conclude that a person’s sex has no relation to the person’s occupation.</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Percent</th><th>N</th><th>Percent</th><th>N</th><th>Percent</th></tr></thead><tbody><tr><td></td><td>Cases</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Valid</td><td>Missing</td><td>Total</td><td></td><td></td><td></td></tr><tr><td>occupation × sex</td><td>54</td><td>96.4%</td><td>2</td><td>3.6%</td><td>56</td><td>100.0%</td></tr><tr><td></td><td></td><td></td><td>sex</td><td>Total</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>occupation</td><td>Artist</td><td>Count</td><td>2</td><td>6</td><td>8</td><td></td></tr><tr><td>Expected</td><td>4.89</td><td>3.11</td><td>.15</td><td></td><td></td><td></td></tr><tr><td>Baker</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Barrister</td><td>Count</td><td>0</td><td>1</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Carpenter</td><td>Count</td><td>3</td><td>1</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Cleaner</td><td>Count</td><td>4</td><td>0</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Cook</td><td>Count</td><td>3</td><td>2</td><td>5</td><td></td><td></td></tr><tr><td>Expected</td><td>3.06</td><td>1.94</td><td>.09</td><td></td><td></td><td></td></tr><tr><td>Manager</td><td>Count</td><td>4</td><td>4</td><td>8</td><td></td><td></td></tr><tr><td>Expected</td><td>4.89</td><td>3.11</td><td>.15</td><td></td><td></td><td></td></tr><tr><td>Mathematician</td><td>Count</td><td>3</td><td>1</td><td>4</td><td></td><td></td></tr><tr><td>Expected</td><td>2.44</td><td>1.56</td><td>.07</td><td></td><td></td><td></td></tr><tr><td>Painter</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Payload Specialist</td><td>Count</td><td>1</td><td>0</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Plumber</td><td>Count</td><td>5</td><td>0</td><td>5</td><td></td><td></td></tr><tr><td>Expected</td><td>3.06</td><td>1.94</td><td>.09</td><td></td><td></td><td></td></tr><tr><td>Scientist</td><td>Count</td><td>5</td><td>2</td><td>7</td><td></td><td></td></tr><tr><td>Expected</td><td>4.28</td><td>2.72</td><td>.13</td><td></td><td></td><td></td></tr><tr><td>Scrientist</td><td>Count</td><td>0</td><td>1</td><td>1</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>.02</td><td></td><td></td><td></td></tr><tr><td>Tailor</td><td>Count</td><td>1</td><td>1</td><td>2</td><td></td><td></td></tr><tr><td>Expected</td><td>1.22</td><td>.78</td><td>.04</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>Count</td><td>33</td><td>21</td><td>54</td><td></td><td></td></tr><tr><td>Expected</td><td>.61</td><td>.39</td><td>1.00</td><td></td><td></td><td></td></tr><tr><td></td><td>Value</td><td>df</td><td>Asymptotic Sig. (2-tailed)</td><td></td><td></td><td></td></tr><tr><td>Pearson Chi-Square</td><td>15.59</td><td>13</td><td>.272</td><td></td><td></td><td></td></tr><tr><td>Likelihood Ratio</td><td>19.66</td><td>13</td><td>.104</td><td></td><td></td><td></td></tr><tr><td>N of Valid Cases</td><td>54</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Results 15.1:</strong> The results of a test of independence between <strong>sex</strong> and <strong>occupation</strong></p>`,82)])])}const m=d(o,[["render",n]]);export{u as __pageData,m as default};
